const listWasteInRange = `-- name: ListWasteInRange :many
SELECT w.id, w.request_id, w.inventory_item_id, w.menu_item_id, w.variant_id, w.modifier_ids, w.name_en, w.name_ne, w.unit, w.quantity_milli, w.reason, w.note, w.by_user_id, w.approved_by_user_id, w.at, w.value_paisa, COALESCE(u.name, '')::text AS by_name, COALESCE(a.name, '')::text AS approved_by_name
FROM waste_entries w
JOIN users u ON u.id = w.by_user_id
LEFT JOIN users a ON a.id = w.approved_by_user_id
WHERE w.at >= $1 AND w.at <= $2
ORDER BY w.at DESC, w.id DESC
`

